// Confirmado contra uma execucao real: o n8n embrulha o corpo do webhook
// em {headers, body, ...} - o payload da Evolution esta em .body, nao direto
// no item. E o data.key.remoteJid pode vir como um identificador "lid" (modo
// de enderecamento por privacidade do WhatsApp), nao o telefone real - o
// campo body.sender e o que a Evolution ja resolve como o numero de verdade.
const wrapper = $input.first().json;
const body = wrapper.body;
const data = body?.data;

if (!data || !data.key || data.key.fromMe) {
  // mensagem enviada pelo proprio bot, ou payload sem o formato esperado: ignora
  return [];
}

const texto =
  data.message?.conversation ??
  data.message?.extendedTextMessage?.text ??
  "";

if (!texto) {
  // mensagem sem texto (audio, imagem, etc.) - por enquanto o bot so trata texto
  return [];
}

const numeroBruto = body.sender || data.key.remoteJid;
const telefone = "+" + numeroBruto.split("@")[0];

return [{ json: { telefone, texto } }];

return [{
  json: {
    telefone: $('Extrair e Filtrar').first().json.telefone,
    mensagem: "Nao encontramos seu cadastro em nosso sistema. Entre em contato com o escritorio."
  }
}];

const cliente = $('Buscar Cliente').first().json;
const conversa = $input.first().json; // objeto vazio {} se nao existir (alwaysOutputData)
const conversaExiste = !!conversa.ultima_mensagem_em;

const agora = new Date();
const sessaoValida = !!(
  conversaExiste &&
  conversa.verificado_em &&
  (agora.getTime() - new Date(conversa.ultima_mensagem_em).getTime()) < 24 * 60 * 60 * 1000
);

return [{
  json: {
    telefone: $('Extrair e Filtrar').first().json.telefone,
    texto: $('Extrair e Filtrar').first().json.texto,
    clienteId: cliente.id,
    clienteCpf: cliente.cpf,
    advogadoId: cliente.advogado_id,
    conversaExiste,
    tentativasFalhas: conversa.tentativas_falhas ?? 0,
    sessaoValida
  }
}];

const item = $input.first().json;
const digitosRecebidos = (item.texto || "").replace(/\D/g, "").slice(-4);
const digitosEsperados = (item.clienteCpf || "").replace(/\D/g, "").slice(-4);

if (!item.conversaExiste) {
  return [{
    json: {
      ...item,
      acao: "pedir_cpf",
      mensagem: "Para sua seguranca, confirme os 4 ultimos digitos do seu CPF antes de continuarmos.",
      novoVerificadoEm: null,
      novasTentativas: 0,
      motivoEscalonamento: null
    }
  }];
}

const confirmou = digitosRecebidos.length === 4 && digitosRecebidos === digitosEsperados;

if (confirmou) {
  return [{
    json: {
      ...item,
      acao: "confirmado",
      mensagem: "Identidade confirmada! Pode repetir sua pergunta.",
      novoVerificadoEm: new Date().toISOString(),
      novasTentativas: 0,
      motivoEscalonamento: null
    }
  }];
}

const novasTentativas = (item.tentativasFalhas || 0) + 1;

if (novasTentativas >= 3) {
  return [{
    json: {
      ...item,
      acao: "escalar_falha",
      mensagem: "Nao conseguimos confirmar sua identidade. Um advogado vai entrar em contato.",
      motivoEscalonamento: "falha na verificacao",
      novoVerificadoEm: null,
      novasTentativas
    }
  }];
}

return [{
  json: {
    ...item,
    acao: "tentar_de_novo",
    mensagem: "Nao conferiu. Pode confirmar novamente os 4 ultimos digitos do seu CPF?",
    novoVerificadoEm: null,
    novasTentativas,
    motivoEscalonamento: null
  }
}];

const item = $input.first().json;
const textoIA = item.output || item.text || "";

const precisaEscalar = /\[ESCALAR\]/i.test(textoIA);
const mensagem = textoIA.replace(/\[ESCALAR\][\s\S]*/i, "").trim();
const motivoMatch = textoIA.match(/\[ESCALAR\]\s*(.*)/i);
const motivoEscalonamento = motivoMatch ? motivoMatch[1].trim() : "fora do escopo";

return [{
  json: {
    telefone: $('Calcular Sessao').first().json.telefone,
    texto: $('Calcular Sessao').first().json.texto,
    clienteId: $('Calcular Sessao').first().json.clienteId,
    advogadoId: $('Calcular Sessao').first().json.advogadoId,
    mensagem: mensagem || "Vou encaminhar sua mensagem para um advogado.",
    precisaEscalar,
    motivoEscalonamento
  }
}];
